  const d = SC.coin_d; sp.scale.set(d * 1.15, d * 1.15, 1); at(s, sp.position).addScaledVector(frameAt(s).n, d * 0.75); sp.renderOrder = 10; scene.add(sp); coins.push({ s, lat: 0, sp, got: -1 });
